    "summary": "<p dir=\"ltr\">Position Name: UiPath Development Manager</p>",
    "fullDescription": "<h3 dir=\"ltr\"> </h3>\r\n\r\n<p dir=\"ltr\">Position Name: UiPath Development Manager</p>\r\n\r\n<p dir=\"ltr\">Location: Remote</p>\r\n\r\n<p dir=\"ltr\">Job Type: Full-Time</p>\r\n<strong>Job Summary:</strong>\r\n\r\n<p dir=\"ltr\">We are seeking an experienced <b>UiPath</b> <strong>Development Manager</strong> to lead and oversee the development and implementation of automation solutions using the UiPath platform. The ideal candidate will have a strong background in Robotic Process Automation (RPA), software development, and team leadership. This role requires expertise in UiPath development, automation best practices, and project management, ensuring the successful delivery of automation initiatives that drive operational efficiency.</p>\r\n\r\n<h3 dir=\"ltr\">Key Responsibilities:</h3>\r\n\r\n<h3 dir=\"ltr\">Leadership & Strategy:</h3>\r\n\r\n<ul>\r\n\t<li dir=\"ltr\">\r\n\t<p dir=\"ltr\" role=\"presentation\">Lead and manage an inshore development team focused on UiPath automation projects.</p>\r\n\t</li>\r\n\t<li dir=\"ltr\">\r\n\t<p dir=\"ltr\" role=\"presentation\">Define and implement best practices for RPA development, governance, and scalability.</p>\r\n\t</li>\r\n\t<li dir=\"ltr\">\r\n\t<p dir=\"ltr\" role=\"presentation\">Collaborate with stakeholders to align automation solutions with business objectives.</p>\r\n\t</li>\r\n\t<li dir=\"ltr\">\r\n\t<p dir=\"ltr\" role=\"presentation\">Drive innovation and continuous improvement in RPA development processes.</p>\r\n\t</li>\r\n</ul>\r\n\r\n<h3 dir=\"ltr\">Technical Oversight:</h3>\r\n\r\n<ul>\r\n\t<li dir=\"ltr\">\r\n\t<p dir=\"ltr\" role=\"presentation\">Provide hands-on technical leadership in UiPath development, deployment, and support.</p>\r\n\t</li>\r\n\t<li dir=\"ltr\">\r\n\t<p dir=\"ltr\" role=\"presentation\">Ensure adherence to coding standards, security policies, and compliance guidelines.</p>\r\n\t</li>\r\n\t<li dir=\"ltr\">\r\n\t<p dir=\"ltr\" role=\"presentation\">Guide the team in building reusable automation frameworks and components.</p>\r\n\t</li>\r\n\t<li dir=\"ltr\">\r\n\t<p dir=\"ltr\" role=\"presentation\">Troubleshoot and resolve complex technical challenges related to automation solutions.</p>\r\n\t</li>\r\n</ul>\r\n\r\n<h3 dir=\"ltr\">Project & Resource Management:</h3>\r\n\r\n<ul>\r\n\t<li dir=\"ltr\">\r\n\t<p dir=\"ltr\" role=\"presentation\">Oversee project timelines, deliverables, and resource allocation.</p>\r\n\t</li>\r\n\t<li dir=\"ltr\">\r\n\t<p dir=\"ltr\" role=\"presentation\">Coordinate with offshore and nearshore teams for seamless automation delivery.</p>\r\n\t</li>\r\n\t<li dir=\"ltr\">\r\n\t<p dir=\"ltr\" role=\"presentation\">Ensure efficient utilization of resources while maintaining high-quality standards.</p>\r\n\t</li>\r\n\t<li dir=\"ltr\">\r\n\t<p dir=\"ltr\" role=\"presentation\">Monitor and report on project progress, risks, and performance metrics.</p>\r\n\t</li>\r\n</ul>\r\n\r\n<h3 dir=\"ltr\">Collaboration & Stakeholder Engagement:</h3>\r\n\r\n<ul>\r\n\t<li dir=\"ltr\">\r\n\t<p dir=\"ltr\" role=\"presentation\">Work closely with business analysts, process owners, and IT teams to identify automation opportunities.</p>\r\n\t</li>\r\n\t<li dir=\"ltr\">\r\n\t<p dir=\"ltr\" role=\"presentation\">Communicate technical solutions to non-technical stakeholders effectively.</p>\r\n\t</li>\r\n\t<li dir=\"ltr\">\r\n\t<p dir=\"ltr\" role=\"presentation\">Ensure smooth handover of automation projects to operations and support teams.</p>\r\n\t</li>\r\n</ul>\r\n\r\n<h3 dir=\"ltr\">Required Qualifications:</h3>\r\n\r\n<ul>\r\n\t<li dir=\"ltr\">\r\n\t<p dir=\"ltr\" role=\"presentation\">5+ years of experience in RPA development and team management, preferably with UiPath.</p>\r\n\t</li>\r\n\t<li dir=\"ltr\">\r\n\t<p dir=\"ltr\" role=\"presentation\">Strong expertise in UiPath Studio, Orchestrator, and Automation Hub.</p>\r\n\t</li>\r\n\t<li dir=\"ltr\">\r\n\t<p dir=\"ltr\" role=\"presentation\">Experience with UiPath AI Center, Document Understanding, and Action Center is a plus.</p>\r\n\t</li>\r\n\t<li dir=\"ltr\">\r\n\t<p dir=\"ltr\" role=\"presentation\">Solid understanding of automation design principles, process optimization, and governance.</p>\r\n\t</li>\r\n\t<li dir=\"ltr\">\r\n\t<p dir=\"ltr\" role=\"presentation\">Proficiency in C#, <a data-saferedirecturl=\"https://www.google.com/url?q=http://vb.net/&source=gmail&ust=1768479355981000&usg=AOvVaw0lBrPPjfCIu7WT_U4xxkPS\" href=\"http://vb.net/\" target=\"_blank\">VB.NET</a>, Python, or other scripting languages for automation enhancement.</p>\r\n\t</li>\r\n\t<li dir=\"ltr\">\r\n\t<p dir=\"ltr\" role=\"presentation\">Strong with API integrations, SQL databases, and cloud environments (AWS/Azure/GCP).</p>\r\n\t</li>\r\n\t<li dir=\"ltr\">\r\n\t<p dir=\"ltr\" role=\"presentation\">Strong leadership, problem-solving, and communication skills.</p>\r\n\t</li>\r\n\t<li dir=\"ltr\">\r\n\t<p dir=\"ltr\" role=\"presentation\">UiPath Advanced Developer Certification is preferred.</p>\r\n\t</li>\r\n</ul>\r\n\r\n<h3 dir=\"ltr\">Preferred Qualifications:</h3>\r\n\r\n<ul>\r\n\t<li dir=\"ltr\">\r\n\t<p dir=\"ltr\" role=\"presentation\">Experience working in financial services, healthcare, or enterprise automation projects.</p>\r\n\t</li>\r\n\t<li dir=\"ltr\">\r\n\t<p dir=\"ltr\" role=\"presentation\">Knowledge of Agile/Scrum methodologies and experience in managing sprint-based automation projects.</p>\r\n\t</li>\r\n\t<li dir=\"ltr\">\r\n\t<p dir=\"ltr\" role=\"presentation\">Exposure to other RPA tools (Automation Anywhere, Blue Prism) is a plus.</p>\r\n\t</li>\r\n</ul>",
